package com.dhanantry.scapeandrunparasites.world.gen;

import net.minecraft.core.BlockPos;
import net.minecraft.util.RandomSource;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;

/**
 * The 1.12 {@code net.minecraft.world.gen.feature.WorldGenerator}: the parasite structures, trees and flowers are generated by
 * calling {@link #generate} directly (from blocks, entities and the world generation hooks), so they stay plain classes
 * instead of becoming 1.21 {@code Feature}s.
 */
public abstract class WorldGenerator {
    private final boolean doBlockNotify;

    public WorldGenerator() {
        this(false);
    }

    public WorldGenerator(boolean notify) {
        this.doBlockNotify = notify;
    }

    public abstract boolean generate(Level worldIn, RandomSource rand, BlockPos position);

    public void setDecorationDefaults() {
    }

    protected void setBlockAndNotifyAdequately(Level worldIn, BlockPos pos, BlockState state) {
        if (this.doBlockNotify) {
            worldIn.setBlock(pos, state, 3);
        } else {
            worldIn.setBlock(pos, state, 2);
        }
    }
}
